CREATE TABLE "FaqEntry" (
  "id"             TEXT NOT NULL,
  "faqCode"        TEXT NOT NULL,
  "category"       TEXT NOT NULL,
  "question"       TEXT NOT NULL,
  "answer"         TEXT NOT NULL,
  "keywords"       TEXT[] NOT NULL DEFAULT '{}',
  "relatedService" TEXT,
  "displayOrder"   INTEGER NOT NULL DEFAULT 0,
  "active"         BOOLEAN NOT NULL DEFAULT true,
  "internalNote"   TEXT,
  "version"        INTEGER NOT NULL DEFAULT 1,
  "lastReviewedAt" TIMESTAMP(3),
  "reviewedBy"     TEXT,
  "createdAt"      TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt"      TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "FaqEntry_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "FaqEntry_faqCode_key" ON "FaqEntry"("faqCode");
CREATE INDEX "FaqEntry_category_displayOrder_idx" ON "FaqEntry"("category", "displayOrder");
CREATE INDEX "FaqEntry_active_idx" ON "FaqEntry"("active");

