INSERT INTO "FaqEntry" ("id","faqCode","category","question","answer","keywords","relatedService","displayOrder","active","version","updatedAt") VALUES
(gen_random_uuid(),'FAQ-001','About Life Energy Centre','What is Life Energy Centre?','Life Energy Centre is a holistic wellness centre in New Town, Kolkata, offering Pranic Healing, meditation, wellness counselling and structured learning programmes in a peaceful and supportive environment.',ARRAY['about','centre','holistic','wellness','pranic healing','meditation'],'General',1,true,1,NOW()),
(gen_random_uuid(),'FAQ-002','About Life Energy Centre','What services do you offer?','We offer wellness counselling, Pranic Healing sessions, guided meditation, healing programmes, Pranic Healing courses, workshops and community activities.',ARRAY['services','counselling','healing','meditation','courses','workshops'],'General',2,true,1,NOW()),
(gen_random_uuid(),'FAQ-003','About Life Energy Centre','Where is Life Energy Centre located?','We are located in New Town, Kolkata.',ARRAY['location','address','new town','kolkata'],'General',3,true,1,NOW()),
(gen_random_uuid(),'FAQ-004','About Life Energy Centre','Who can visit Life Energy Centre?','Anyone interested in exploring holistic wellness, meditation, Pranic Healing or personal development is welcome. No previous experience is required for introductory activities.',ARRAY['visit','who','welcome','beginner','experience'],'General',4,true,1,NOW()),
(gen_random_uuid(),'FAQ-005','About Life Energy Centre','Do I need an appointment?','Appointments are recommended so that we can provide adequate time and personal attention. Walk-in visitors may be accommodated subject to availability.',ARRAY['appointment','walk-in','availability'],'General',5,true,1,NOW()),
(gen_random_uuid(),'FAQ-006','Pranic Healing','What is Pranic Healing?','Pranic Healing is a complementary, no-touch energy-based wellness practice founded by Grand Master Choa Kok Sui. It works with the body''s energy system using techniques such as cleansing and energising.',ARRAY['pranic healing','energy','choa kok sui','complementary','no-touch'],'Pranic Healing',1,true,1,NOW()),
(gen_random_uuid(),'FAQ-007','Pranic Healing','Does Pranic Healing involve physical touch?','No. Pranic Healing is generally performed without physical touch.',ARRAY['touch','no-touch','physical','contact'],'Pranic Healing',2,true,1,NOW()),
(gen_random_uuid(),'FAQ-008','Pranic Healing','Is Pranic Healing a medical treatment?','No. Pranic Healing is a complementary wellness practice and is not a substitute for medical diagnosis, treatment or emergency medical care. Please continue any medical treatment prescribed by your qualified healthcare professional.',ARRAY['medical','treatment','substitute','doctor','healthcare'],'Pranic Healing',3,true,1,NOW()),
(gen_random_uuid(),'FAQ-009','Pranic Healing','What can Pranic Healing help with?','People explore Pranic Healing for a variety of reasons, including relaxation, stress management, emotional well-being, personal development and overall wellness. Individual experiences vary, and no particular result can be guaranteed.',ARRAY['help','stress','relaxation','emotional','wellbeing','benefits'],'Pranic Healing',4,true,1,NOW()),
(gen_random_uuid(),'FAQ-010','Pranic Healing','Can Pranic Healing be used along with medical treatment?','Pranic Healing may be explored as a complementary wellness practice. It should not replace prescribed medical treatment. If you have a medical condition, please continue consulting your qualified healthcare professional.',ARRAY['medical','complementary','alongside','treatment','doctor'],'Pranic Healing',5,true,1,NOW()),
(gen_random_uuid(),'FAQ-011','Pranic Healing','How does Pranic Healing work?','Pranic Healing uses techniques involving cleansing and energising of the energy system. The practice also includes work with chakras and meditation. A counsellor or healer can explain the process in greater detail during an introductory experience.',ARRAY['how','works','chakras','cleansing','energising','technique'],'Pranic Healing',6,true,1,NOW()),
(gen_random_uuid(),'FAQ-012','Pranic Healing','How long does a healing session take?','The duration may vary depending on the type of session and the Centre''s schedule. Please check the appointment details provided to you or contact the Centre.',ARRAY['duration','time','how long','session','schedule'],'Pranic Healing',7,true,1,NOW()),
(gen_random_uuid(),'FAQ-013','Pranic Healing','Will one healing session be enough?','Every individual''s experience is different. Some people may wish to continue with additional sessions, while others may simply wish to explore meditation or learning. Your next step should be based on your own experience and comfort.',ARRAY['one session','enough','continue','multiple sessions','experience'],'Pranic Healing',8,true,1,NOW()),
(gen_random_uuid(),'FAQ-014','Appointments','How can I book an appointment?','You can book through the CRM/client portal, WhatsApp, telephone, or by contacting the Centre.',ARRAY['book','appointment','how','portal','whatsapp','contact'],'Appointments',1,true,1,NOW()),
(gen_random_uuid(),'FAQ-015','Appointments','Can I choose a particular healer?','Where available, you may request a particular healer. The appointment system will show availability according to the healer''s individual calendar.',ARRAY['healer','choose','prefer','request','specific'],'Appointments',2,true,1,NOW()),
(gen_random_uuid(),'FAQ-016','Appointments','Can I change my appointment?','Yes. Please inform us as early as possible so that the appointment can be rescheduled subject to availability.',ARRAY['change','reschedule','appointment','modify'],'Appointments',3,true,1,NOW()),
(gen_random_uuid(),'FAQ-017','Appointments','What happens if I miss my appointment?','Please contact us when convenient. We will help you find another suitable appointment, subject to availability.',ARRAY['missed','no show','missed appointment','reschedule'],'Appointments',4,true,1,NOW()),
(gen_random_uuid(),'FAQ-018','Appointments','How early should I arrive?','We recommend arriving approximately 10–15 minutes before your scheduled centre appointment.',ARRAY['arrive','early','on time','before','punctual'],'Appointments',5,true,1,NOW()),
(gen_random_uuid(),'FAQ-019','Appointments','Can I cancel an appointment?','Yes. Please inform the Centre as early as possible. Cancellation and rescheduling conditions, where applicable, will be communicated at the time of booking.',ARRAY['cancel','cancellation','appointment'],'Appointments',6,true,1,NOW()),
(gen_random_uuid(),'FAQ-020','Healing Sessions','What happens during a healing session?','Depending on the session, it may include a brief discussion, chakra assessment, energy cleansing and energising, and appropriate guidance after the session.',ARRAY['during','session','what happens','chakra','cleansing','discussion'],'Healing Sessions',1,true,1,NOW()),
(gen_random_uuid(),'FAQ-021','Healing Sessions','What should I wear for a healing session?','Comfortable clothing is recommended. There is generally no special dress requirement.',ARRAY['wear','clothing','dress','comfortable','attire'],'Healing Sessions',2,true,1,NOW()),
(gen_random_uuid(),'FAQ-022','Healing Sessions','Can I talk to the healer before the session?','Yes. You may briefly discuss how you have been feeling and share relevant information with the healer.',ARRAY['talk','discuss','before','healer','pre-session'],'Healing Sessions',3,true,1,NOW()),
(gen_random_uuid(),'FAQ-023','Healing Sessions','What happens after the healing?','The healer completes the session record. Where applicable, a client-facing Healing Summary is prepared and made available through the Client Portal.',ARRAY['after','post-session','healing summary','portal','record'],'Healing Sessions',4,true,1,NOW()),
(gen_random_uuid(),'FAQ-024','Healing Sessions','Can I ask questions after my healing?','Yes. You may discuss your questions with the healer or counsellor.',ARRAY['questions','after','post','healer','counsellor'],'Healing Sessions',5,true,1,NOW()),
(gen_random_uuid(),'FAQ-025','Healing Sessions','Can I have regular healing sessions?','Yes. Clients who wish to continue may discuss suitable options with the counsellor.',ARRAY['regular','ongoing','continue','multiple','schedule'],'Healing Sessions',6,true,1,NOW()),
(gen_random_uuid(),'FAQ-026','Healing Summary','What is a Healing Summary?','A Healing Summary is a client-facing record of your healing session. It provides a simple overview of the session and relevant guidance.',ARRAY['healing summary','what is','record','overview'],'Healing Sessions',1,true,1,NOW()),
(gen_random_uuid(),'FAQ-027','Healing Summary','How will I receive my Healing Summary?','Once the healer completes and submits the session record, the CRM generates your Healing Summary. You may receive a secure link through WhatsApp or access it through the Client Portal.',ARRAY['receive','healing summary','whatsapp','portal','link'],'Healing Sessions',2,true,1,NOW()),
(gen_random_uuid(),'FAQ-028','Healing Summary','What information is included in the Healing Summary?','Depending on the session, the summary may include: session date, general areas worked on, simplified chakra information, general observations, suggested practices, and suggested next step.',ARRAY['healing summary','information','chakra','observations','included'],'Healing Sessions',3,true,1,NOW()),
(gen_random_uuid(),'FAQ-029','Healing Summary','Can I see my previous Healing Summaries?','Yes. Previous client-facing Healing Summaries can be made available through the Client Portal, subject to your account access.',ARRAY['previous','past','healing summary','history','portal'],'Healing Sessions',4,true,1,NOW()),
(gen_random_uuid(),'FAQ-030','Healing Summary','Can I share my Healing Summary?','Your Healing Summary is intended for your personal use. Please consider privacy and confidentiality before sharing it with others.',ARRAY['share','healing summary','privacy','confidential'],'Healing Sessions',5,true,1,NOW()),
(gen_random_uuid(),'FAQ-031','Meditation','Who can attend meditation?','Meditation sessions are generally open to anyone interested in learning or practising meditation, subject to the particular programme.',ARRAY['meditation','attend','who','open','programme'],'Meditation',1,true,1,NOW()),
(gen_random_uuid(),'FAQ-032','Meditation','Do I need previous meditation experience?','No. Beginners are welcome unless a particular programme has specific requirements.',ARRAY['meditation','beginner','experience','new','first time'],'Meditation',2,true,1,NOW()),
(gen_random_uuid(),'FAQ-033','Meditation','What should I bring to meditation?','Normally, comfortable clothing and an open mind are sufficient. Any special requirements will be communicated for the particular programme.',ARRAY['meditation','bring','what','clothing','prepare'],'Meditation',3,true,1,NOW()),
(gen_random_uuid(),'FAQ-034','Meditation','How can I join the weekly meditation?','You can check the current schedule through the Centre or Client Portal.',ARRAY['meditation','weekly','join','schedule','how'],'Meditation',4,true,1,NOW()),
(gen_random_uuid(),'FAQ-035','Meditation','Can meditation help with stress?','Meditation is commonly practised to encourage relaxation, calmness and mental focus. Individual experiences vary.',ARRAY['meditation','stress','relaxation','calm','mental','focus'],'Meditation',5,true,1,NOW()),
(gen_random_uuid(),'FAQ-036','Courses','Who can learn Pranic Healing?','Anyone interested in learning the techniques may enquire about the appropriate course. No previous experience is generally required for the Basic Course.',ARRAY['learn','course','who','beginner','pranic healing'],'Courses',1,true,1,NOW()),
(gen_random_uuid(),'FAQ-037','Courses','What is the Basic Pranic Healing Course?','It is a structured introductory course designed to teach the fundamental principles and practical techniques of Pranic Healing.',ARRAY['basic course','what','introductory','fundamental','techniques'],'Courses',2,true,1,NOW()),
(gen_random_uuid(),'FAQ-038','Courses','How long is the Basic Course?','The Basic Course is generally conducted over two days. Please check the current course schedule for the latest dates and timings.',ARRAY['basic course','duration','how long','two days','schedule'],'Courses',3,true,1,NOW()),
(gen_random_uuid(),'FAQ-039','Courses','Will I receive a certificate?','Participants who fulfil the applicable course requirements may receive a certificate in accordance with the course policy.',ARRAY['certificate','course','qualification','receive'],'Courses',4,true,1,NOW()),
(gen_random_uuid(),'FAQ-040','Courses','Can I learn Pranic Healing for myself?','Yes. The course provides techniques that participants can practise for their own personal development and self-care, within the scope of their training.',ARRAY['self','personal','learn','self-care','development'],'Courses',5,true,1,NOW()),
(gen_random_uuid(),'FAQ-041','Courses','Can I help my family after learning?','The Basic Course teaches practical techniques that students may apply within the scope of their training. Students should follow the principles and guidance provided during their course.',ARRAY['family','help','apply','after course','home'],'Courses',6,true,1,NOW()),
(gen_random_uuid(),'FAQ-042','Courses','Are advanced courses available?','Yes, subject to the applicable prerequisites and current course schedule.',ARRAY['advanced','courses','higher','next level','prerequisites'],'Courses',7,true,1,NOW()),
(gen_random_uuid(),'FAQ-043','Payments','What payment methods are accepted?','The Centre may accept cash, UPI, cards, bank transfer and available online payment methods. Please check with the Centre for currently available payment options.',ARRAY['payment','methods','cash','upi','card','online','bank transfer'],'Payments',1,true,1,NOW()),
(gen_random_uuid(),'FAQ-044','Payments','Will I receive a receipt?','Yes. A receipt should be issued for payments made to the Centre.',ARRAY['receipt','payment','invoice','proof'],'Payments',2,true,1,NOW()),
(gen_random_uuid(),'FAQ-045','Payments','Can I pay online?','Where online payment facilities are available, you may use the payment link provided by the Centre.',ARRAY['online payment','pay online','link','digital'],'Payments',3,true,1,NOW()),
(gen_random_uuid(),'FAQ-046','Payments','How can I check my package balance?','Your available package balance can be viewed through the Client Portal where this feature is enabled.',ARRAY['balance','package','credits','portal','check'],'Payments',4,true,1,NOW()),
(gen_random_uuid(),'FAQ-047','Payments','What happens after I purchase a healing package?','Once payment is confirmed, the package is activated in the CRM and the applicable sessions are added to your account. You can then book sessions subject to availability and package terms.',ARRAY['package','purchase','activate','sessions','credits','after payment'],'Payments',5,true,1,NOW()),
(gen_random_uuid(),'FAQ-048','Payments','What is the validity of my package?','Package validity depends on the package selected. Your applicable validity period should be displayed in your client record or communicated at the time of purchase.',ARRAY['validity','package','expiry','duration','period'],'Payments',6,true,1,NOW()),
(gen_random_uuid(),'FAQ-049','Privacy','Is my personal information confidential?','Life Energy Centre treats client information as confidential and limits access to authorised personnel for legitimate purposes.',ARRAY['confidential','private','personal','information','data'],'General',1,true,1,NOW()),
(gen_random_uuid(),'FAQ-050','Privacy','Who can see my healing information?','Access to client information is restricted according to the Centre''s authorisation and CRM access controls.',ARRAY['healing information','access','who sees','restricted','privacy'],'General',2,true,1,NOW()),
(gen_random_uuid(),'FAQ-051','Privacy','Can other clients see my information?','No. Client records are not intended to be accessible to other clients.',ARRAY['other clients','see','records','private','access'],'General',3,true,1,NOW()),
(gen_random_uuid(),'FAQ-052','Privacy','Is my Healing Summary private?','Yes. Your client-facing Healing Summary is provided through your individual client access and should be treated as personal information.',ARRAY['healing summary','private','confidential','personal'],'General',4,true,1,NOW()),
(gen_random_uuid(),'FAQ-053','Privacy','Will my photograph or testimonial be published?','Client photographs, testimonials or other identifiable information should only be used for promotional purposes with appropriate consent.',ARRAY['photograph','testimonial','published','consent','promotional'],'General',5,true,1,NOW()),
(gen_random_uuid(),'FAQ-054','General Questions','Can I bring a family member?','Yes, subject to the nature of the session and available space.',ARRAY['family','bring','accompany','guest'],'General',1,true,1,NOW()),
(gen_random_uuid(),'FAQ-055','General Questions','Can children participate?','Children may participate in appropriate programmes subject to the Centre''s policies and parental/guardian consent where required.',ARRAY['children','kids','participate','age','guardian','consent'],'General',2,true,1,NOW()),
(gen_random_uuid(),'FAQ-056','General Questions','Do you offer online sessions?','Availability of online counselling, meditation or other programmes depends on the current Centre schedule. Please contact the Centre for current availability.',ARRAY['online','virtual','remote','zoom','digital','session'],'General',3,true,1,NOW()),
(gen_random_uuid(),'FAQ-057','General Questions','Can I volunteer at Life Energy Centre?','Volunteer opportunities may be available for eligible students and members of the Centre community. Please contact the Centre for current opportunities.',ARRAY['volunteer','help','contribute','community','student'],'General',4,true,1,NOW()),
(gen_random_uuid(),'FAQ-058','General Questions','How can I give feedback?','You can provide feedback through the Client Portal, WhatsApp, telephone, or directly to the Centre.',ARRAY['feedback','review','opinion','comment','suggestion'],'General',5,true,1,NOW()),
(gen_random_uuid(),'FAQ-059','General Questions','How can I make a complaint?','Please contact the Centre and explain your concern. We will review it respectfully and escalate it to the appropriate person when necessary.',ARRAY['complaint','concern','issue','problem','escalate'],'General',6,true,1,NOW()),
(gen_random_uuid(),'FAQ-060','General Questions','How can I contact Life Energy Centre?','You can contact us by telephone, WhatsApp, or through the contact options provided in your Client Portal.',ARRAY['contact','phone','whatsapp','reach','telephone'],'General',7,true,1,NOW());
